    private fun String.toIdSet(): Set<String> =
        split(',').filter { it.isNotEmpty() }.toSet()

    private val trIds: Set<String> by lazy { TR_IDS.toIdSet() }
    private val tr18Ids: Set<String> by lazy { TR18_IDS.toIdSet() }
    private val globalIds: Set<String> by lazy { GLOBAL_IDS.toIdSet() }
    private val global18Ids: Set<String> by lazy { GLOBAL18_IDS.toIdSet() }
    private val testIds: Set<String> by lazy { TEST_IDS.toIdSet() }
    private val test18Ids: Set<String> by lazy { TEST18_IDS.toIdSet() }

    /** Paket soneki için izinli id kümesi; bilinmeyen pakette null (fabrika patlar). */
    fun allowed(suffix: String): Set<String>? = when (suffix) {
        "tr" -> trIds
        "tr18" -> tr18Ids
        "global" -> globalIds
        "global18" -> global18Ids
        "test" -> testIds
        "test18" -> test18Ids
        else -> null
    }

    private val PATCHES_B64: String = join(
        "",
    )

    private val CATALOGUE_B64: String = join(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    )

    private fun join(vararg parts: String): String = parts.joinToString("")

    // Gömülü veri satır sonlarıyla bölünmüş base64 taşır. Cihazda android.util.Base64
    // NO_WRAP bunu kabul eder; masaüstü harness'ında aynı çağrı "bad base-64" atar ve
    // kaynak listesi boş kalır. Boşluklar temizlenir, olmazsa MIME çözücüsüne düşülür.
    private fun decode(data: String): String {
        val temiz = data.filterNot { it.isWhitespace() }
        runCatching { return String(android.util.Base64.decode(temiz, android.util.Base64.NO_WRAP)) }
        return String(java.util.Base64.getMimeDecoder().decode(temiz))
    }

    private val patches: String by lazy { decode(PATCHES_B64) }
    private val catalogue: String by lazy { decode(CATALOGUE_B64) }

    /** Gömülü veri varsa döner; yoksa null (asset okuma yoluna düşülür). */
    fun embedded(name: String): String? = when (name) {
        "patches.json" -> patches
        "catalogue.json" -> catalogue
        else -> null
    }
